const payload = '<img src=x onerror="alert(1)"> <script>alert(2)</script>';

function safeUrl(url) {
  try {
    const u = new URL(url, "https://example.com");
    return ["http:", "https:", "mailto:"].includes(u.protocol) ? url : "#";
  } catch (e) {
    return "#";
  }
}

function App() {
  const links = ["https://react.dev", "javascript:alert('xss')"];
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <p>User comment (escaped automatically):</p>
      <pre style={{ background: "#f1f5f9", padding: 8, whiteSpace: "pre-wrap" }}>{payload}</pre>
      <ul>
        {links.map((l) => (
          <li key={l}>
            <a href={safeUrl(l)} target="_blank" rel="noopener noreferrer">{l}</a>
            {safeUrl(l) === "#" && " (blocked)"}
          </li>
        ))}
      </ul>
    </div>
  );
}

import DOMPurify from "dompurify";

export function RichText({ html }) {
  const clean = DOMPurify.sanitize(html, { USE_PROFILES: { html: true } });
  return <div dangerouslySetInnerHTML={{ __html: clean }} />;
}

function Broken() {
  const [count, setCount] = useState(0);
  // BAD: new component type on every render -> remount -> state lost
  function Inner() {
    const [text, setText] = useState("");
    return <input value={text} onChange={(e) => setText(e.target.value)} placeholder="Type, then click +1" />;
  }
  return (
    <div>
      <button onClick={() => setCount(count + 1)}>+1 ({count})</button>
      <Inner />
    </div>
  );
}

