function EditForm({ user }) {
  // initial state comes from props only once; key resets it
  const [name, setName] = useState(user.name);
  return (
    <p>
      <input value={name} onChange={(e) => setName(e.target.value)} />
    </p>
  );
}

function App() {
  const users = [{ id: 1, name: "Asha" }, { id: 2, name: "Ravi" }];
  const [id, setId] = useState(1);
  const user = users.find((u) => u.id === id);
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      {users.map((u) => <button key={u.id} onClick={() => setId(u.id)} style={{ marginRight: 6 }}>{u.name}</button>)}
      <EditForm key={user.id} user={user} />
      <small>Edit the name, switch user and back: each user starts fresh.</small>
    </div>
  );
}

