function App() {
  const [count, setCount] = useState(0);
  const [msg, setMsg] = useState("");
  const latest = useRef(count);
  latest.current = count;

  function showLater() {
    setTimeout(() => {
      setMsg("closure saw " + count + ", ref saw " + latest.current);
    }, 1500);
  }
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <button onClick={() => setCount(count + 1)}>+1 ({count})</button>{" "}
      <button onClick={showLater}>Show later (1.5s)</button>
      <p>{msg}</p>
      <small>Click Show later, then +1 a few times: the closure keeps the old number.</small>
    </div>
  );
}

const ITEMS = Array.from({ length: 3000 }, (_, i) => "Entry " + i);

function Results({ q }) {
  const rows = ITEMS.filter((x) => x.includes(q)).slice(0, 200);
  return <ul style={{ maxHeight: 120, overflow: "auto" }}>{rows.map((r) => <li key={r}>{r}</li>)}</ul>;
}

function App() {
