  const [pending, start] = useTransition();
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <input value={input} onChange={(e) => { setInput(e.target.value); start(() => setQ(e.target.value)); }} placeholder="filter" />
