function Broken() {
  const [count, setCount] = useState(0);
  useEffect(() => {
    const id = setInterval(() => setCount(count + 1), 500);   // always 0 + 1
    return () => clearInterval(id);
  }, []);
  return <p>Broken: {count}</p>;
}
function Fixed() {
  const [count, setCount] = useState(0);
  useEffect(() => {
    const id = setInterval(() => setCount((c) => c + 1), 500);
    return () => clearInterval(id);
  }, []);
  return <p>Fixed: {count}</p>;
}
function App() {
  return <div style={{ fontFamily: "sans-serif", padding: 12 }}><Broken /><Fixed /></div>;
}

